```js
function switchAdjectives(sentence) {
  // Split the sentence into an array of words
  const words = sentence.split(" ");

  // Initialize variables for the first and second adjective positions
  let firstAdjIndex = null;
  let secondAdjIndex = null;

  // Loop through the words to find the positions of the first and second adjectives
  for (let i = 0; i < words.length; i++) {
    // If we encounter an adjective, update our index variables
    if (isAdjective(words[i])) {
      // If we haven't found either position yet, set the current position as the first one
      if (firstAdjIndex === null && secondAdjIndex === null) {
        firstAdjIndex = i;
      } else if (secondAdjIndex === null) {
        // Otherwise, it's the second position
        secondAdjIndex = i;
      }
    }
  }

  // If we didn't find any adjectives, there's nothing to do
  if (firstAdjIndex === null || secondAdjIndex === null) return sentence;

  // Swap the positions of the first and second adjectives
  [words[firstAdjIndex], words[secondAdjIndex]] = [words[secondAdjIndex], words[firstAdjIndex]];

  // Join the words back into a sentence
  return words.join(" ");
}

// Helper function to check if a word is an adjective
function isAdjective(word) {
  // This is just a simple heuristic to identify adjectives - you may need to adjust it based on your specific use case
  // Adjectives generally end in '-ly', are before the noun they modify, and don't have a space between them and the noun
  return word.endsWith("ly") || word.lastIndexOf(" ") !== word.indexOf(" ", word.lastIndexOf(" ") + 1);
}
