     name: String,
     address: {
       street: String,
       city: String,
       state: String,
       country: String,
     },
     nestedObjects: [
       { type: NestedModel },
     ],
   });

   export const ParentModel = mongoose.model('ParentModel', ParentSchema);
   ```

