  const ratingB = calculateWeightedRating("HTTP", inputData);
  const ratingC = calculateWeightedRating("UDP", inputData);

  // Determine most relevant protocol based on highest weighted rating
  let mostRelevantProtocol = "";
  if (ratingA > ratingB && ratingA > ratingC) {
    mostRelevantProtocol = "IPv6";
  } else if (ratingB > ratingA && ratingB > ratingC) {
    mostRelevantProtocol = "HTTP";
  } else if (ratingC > ratingA && ratingC > ratingB) {
    mostRelevantProtocol = "UDP";
  }

  return mostRelevantProtocol;
}

